package org.codex.nfsugpreview;
import java.io.*;import java.util.*;
public final class HudRulesTest {public static void main(String[] args)throws Exception{int pixels,windows,accepted=0,rejected=0,checks=0;try(DataInputStream in=new DataInputStream(new FileInputStream(args[0]))){if(in.readInt()!=0x31524448)throw new AssertionError("Header");pixels=in.readInt();windows=in.readInt();for(int i=0;i<pixels;i++){int obj=in.readInt(),tag=in.readInt(),bg=in.readInt(),priority=in.readInt(),backdrop=in.readInt(),blend=in.readInt(),alpha=in.readInt(),brightness=in.readInt(),expected=in.readInt();if(NativeHudRules.pixel(obj,tag,bg,priority,backdrop,blend,alpha,brightness)!=expected)throw new AssertionError("HUD blend "+i);}for(int i=0;i<windows;i++){int display=in.readInt(),row=in.readInt();int[] regs=new int[6];for(int k=0;k<6;k++)regs[k]=in.readInt();int[] before=regs.clone();boolean expected=in.readInt()!=0;byte[] visible=new byte[expected?240:0],backdrop=new byte[visible.length];in.readFully(visible);in.readFully(backdrop);NativeHudRules.Windows result=null;boolean good=true;try{result=NativeHudRules.windows(display,row,regs);}catch(IllegalArgumentException invalid){good=false;}if(good!=expected)throw new AssertionError("Window acceptance "+i);if(!Arrays.equals(before,regs))throw new AssertionError("Window mutation");if(good){accepted++;if(!Arrays.equals(visible,result.visible())||!Arrays.equals(backdrop,result.backdrop()))throw new AssertionError("Window controls "+i);byte[] copy=result.backdrop();copy[0]^=1;if(!Arrays.equals(backdrop,result.backdrop()))throw new AssertionError("Borrowed output");checks+=480;}else rejected++;}if(in.read()!=-1)throw new AssertionError("Trailing data");}System.out.println("PASS_HUD_RULES blend_cases="+pixels+" window_cases="+windows+" accepted="+accepted+" rejected="+rejected+" exact_window_checks="+checks+" input_immutable=true output_owned=true");}}
